/**
 * Server-side SFTP proxy for the in-portal file manager.
 *
 * This is a plain (non-"use server") module so it can be imported by both the
 * server actions (lib/actions-files.ts) and the upload/download route handler.
 * It never runs in the browser — the customer's root credentials stay on the
 * server; the browser only ever talks to our own actions/route.
 *
 * Connection target is derived EXACTLY like the server detail page:
 *   - dedicated-IP servers connect to their own IP on port 22
 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
 * Username is always "root"; password is `server.rootPassword`.
 *
 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
 * every op is backed by a small in-memory simulated filesystem so the whole
 * file-manager UX works end to end without a live VM.
 */
import SftpClient from "ssh2-sftp-client";
import { SANDBOX } from "./sandbox";
import { createHash } from "node:crypto";
import { decryptSecret } from "./crypto-box";
import { ConnPool, isConnectionError } from "./sftp-pool";

/**
 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
 * value and falling back to the legacy plaintext column for rows that predate
 * encryption. Every READ of a root password must go through this helper so both
 * shapes keep working transparently.
 */
export function serverRootPassword(
  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
): string | null {
  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
}

/**
 * Resolve a server's decrypted OpenSSH-format management PRIVATE key, if one has
 * been generated for it (see Server.sshManagementKeyEnc's schema doc comment).
 * Null for any server not yet provisioned/backfilled with one.
 */
export function serverManagementKey(
  server: { sshManagementKeyEnc?: string | null }
): string | null {
  return decryptSecret(server.sshManagementKeyEnc);
}

/** The minimal shape of a Server we need to open a connection. */
export type SftpServer = {
  id: string;
  rootPassword: string | null;
  rootPasswordEnc?: string | null;
  /** See Server.sshManagementKeyEnc's schema doc comment. Optional so every
   *  existing caller that doesn't select it keeps today's password-only path. */
  sshManagementKeyEnc?: string | null;
  sshPort: number | null;
  dedicatedIp?: { address: string } | null;
  /** The server's own node — vmids/ports are per-node, so a NAT (non-dedicated-IP)
   *  server's real SSH host is THIS node's public IP, not necessarily the
   *  platform's env-configured primary. Optional so existing callers that don't
   *  select it keep today's exact fallback behavior (see connectionTarget). */
  node?: { publicIp: string } | null;
  /** See Server.guestSshPort's schema doc comment. Only meaningful on a
   *  dedicated-IP server — optional so a caller that doesn't select it keeps
   *  today's "assume port 22" behavior via connectionTarget's `?? 22`. */
  guestSshPort?: number | null;
};

export type SftpEntry = {
  name: string;
  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
  type: string;
  isDirectory: boolean;
  size: number;
  /** Unix mtime in ms. */
  modifiedMs: number;
  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
  mode: number | null;
};

export type SftpStat = {
  isDirectory: boolean;
  size: number;
  modifiedMs: number;
  mode: number | null;
};

const CONNECT_TIMEOUT_MS = 10_000;

/** Max length for any absolute path we accept from the client. */
export const MAX_PATH_LEN = 4096;
/** Max length for a single path segment (file/folder name). */
export const MAX_NAME_LEN = 255;

/**
 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
 * "/". Throws on anything suspicious — callers surface the message.
 */
export function normalizePath(input: string): string {
  if (typeof input !== "string") throw new Error("Invalid path.");
  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
  if (input.includes("\0")) throw new Error("Invalid path.");
  if (!input.startsWith("/")) throw new Error("Path must be absolute.");

  const out: string[] = [];
  for (const part of input.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") throw new Error("Path traversal is not allowed.");
    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
    out.push(part);
  }
  return "/" + out.join("/");
}

/**
 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
 * not "." or "..". Returns the name unchanged if valid.
 */
export function validateName(name: string): string {
  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
  if (name === "." || name === "..") throw new Error("That name is not allowed.");
  return name;
}

/** Join a validated absolute dir with a validated name, re-normalizing. */
export function joinPath(dir: string, name: string): string {
  return normalizePath(`${dir}/${name}`);
}

/**
 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
 * written here under a sanitized basename — never at a client-chosen path — so
 * a hostile filename can only ever create a file inside this one dir. Lives in
 * this plain module (not the "use server" action file) so it can be imported
 * and unit-tested without pulling in the server-action graph.
 */
export const UPLOAD_DIR = "/root/nxeon-uploads";

/**
 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final
 * segment, then runs the survivor through the same `validateName` the file
 * manager uses (rejects `/`, NUL, `.`, `..`, over-long names). Pure so the guard
 * can be unit-tested in isolation from any SFTP connection.
 */
export function sanitizeUploadName(raw: string): string {
  if (typeof raw !== "string") throw new Error("A name is required.");
  const base = raw.split(/[/\\]/).pop() ?? "";
  const trimmed = base.trim();
  if (!trimmed) throw new Error("A name is required.");
  return validateName(trimmed);
}

/**
 * Resolve the {host, port} for a server, mirroring the server detail page:
 * dedicated IP -> :22, otherwise the server's OWN node's public IP : sshPort
 * (falling back to the platform's env-configured primary only when the
 * server genuinely has no node relation — e.g. not yet selected by an older
 * caller, or a row that predates multi-node). Getting this wrong for a
 * server on a non-primary node means dialing the WRONG physical host
 * entirely, not just a wrong port — verified live 2026-09-05 as the root
 * cause of an entire class of "control panel dead for node-2" bugs.
 */
export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
  const dedicated = !!server.dedicatedIp;
  const host = dedicated ? server.dedicatedIp!.address : (server.node?.publicIp ?? process.env.PUBLIC_IP ?? "");
  const port = dedicated ? (server.guestSshPort ?? 22) : server.sshPort;
  if (!host || !port) return null;
  return { host, port };
}

/**
 * Open one SFTP connection: the per-server management key first, falling back to the root
 * password (see the long note on Server.sshManagementKeyEnc). A fresh client per attempt:
 * reusing one after a failed connect is not a state ssh2-sftp-client guarantees to recover from.
 */
async function connectSftp(
  target: { host: string; port: number },
  privateKey: string | null,
  password: string | null
): Promise<SftpClient> {
  if (privateKey) {
    const keyClient = new SftpClient();
    try {
      await keyClient.connect({
        host: target.host,
        port: target.port,
        username: "root",
        privateKey,
        readyTimeout: CONNECT_TIMEOUT_MS,
      });
      return keyClient;
    } catch (e) {
      try { await keyClient.end(); } catch { /* best effort */ }
      if (!password) throw e;
    }
  }
  const client = new SftpClient();
  try {
    await client.connect({
      host: target.host,
      port: target.port,
      username: "root",
      password: password!,
      readyTimeout: CONNECT_TIMEOUT_MS,
    });
    return client;
  } catch (e) {
    try { await client.end(); } catch { /* best effort */ }
    throw e;
  }
}

/** Idle-expiring pool for READ operations (list/read); see lib/sftp-pool.ts for the security model. */
const globalForPool = globalThis as unknown as { __nxeonSftpPool?: ConnPool<SftpClient> };
const sftpPool: ConnPool<SftpClient> =
  globalForPool.__nxeonSftpPool ??
  (globalForPool.__nxeonSftpPool = new ConnPool<SftpClient>({
    idleMs: 25_000,
    maxEntries: 32,
    close: async (c) => { await c.end(); },
  }));

/** Short non-reversible fingerprint of the credential, so a rotated password/key abandons the pooled connection. */
function credFingerprint(privateKey: string | null, password: string | null): string {
  return createHash("sha256").update(`${privateKey ?? ""}\u0000${password ?? ""}`).digest("hex").slice(0, 16);
}

/**
 * Open an SFTP connection, run `fn(client)`, and close it (finally) — OR, when `opts.poolKey` is
 * given, run on a short-lived pooled connection instead. `poolKey` MUST be derived from the
 * authenticated user id and the server id by the caller (lib/actions-files.ts does
 * `${user.id}:${server.id}`) AFTER the ownership check; it is combined here with the target and a
 * credential fingerprint. Only use it for read operations.
 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
 * the in-memory filesystem before ever reaching here.
 */
export async function withSftp<T>(
  server: SftpServer,
  fn: (client: SftpClient) => Promise<T>,
  opts?: { poolKey?: string }
): Promise<T> {
  if (SANDBOX) {
    throw new Error("withSftp must not be called in sandbox mode");
  }
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password set.");

  if (opts?.poolKey) {
    const key = `${opts.poolKey}|${target.host}:${target.port}|${credFingerprint(privateKey, password)}`;
    return sftpPool.run(
      key,
      async () => {
        const c = await connectSftp(target, privateKey, password);
        // A dead connection must never be handed out again.
        const gone = () => sftpPool.drop(key, c);
        c.on("close", gone);
        c.on("end", gone);
        c.on("error", gone);
        return c;
      },
      fn,
      isConnectionError
    );
  }

  const client = await connectSftp(target, privateKey, password);
  try {
    return await fn(client);
  } finally {
    try {
      await client.end();
    } catch {
      /* best-effort close */
    }
  }
}

// ----------------------------------------------------------------------------
// Sandbox in-memory filesystem
// ----------------------------------------------------------------------------

type SimNode =
  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
  | { type: "file"; mtime: number; mode: number; content: string };
type SimDir = Extract<SimNode, { type: "dir" }>;

/** One simulated filesystem per server id, lazily seeded. */
const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
globalForSim.__nxeonSftpSim = simStore;

function seedSim(): SimNode {
  const now = Date.now();
  const file = (content: string, mode = 0o644): SimNode => ({
    type: "file",
    mtime: now,
    mode,
    content,
  });
  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
    type: "dir",
    mtime: now,
    mode,
    children,
  });
  return dir({
    root: dir({
      "readme.txt": file(
        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
      ),
      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
      projects: dir({
        "app.js": file("console.log('hello from your server');\n"),
        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
      }),
    }),
    etc: dir({
      "hostname": file("nxeon-vps\n"),
      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
    }),
    var: dir({
      log: dir({
        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
      }),
      www: dir({
        html: dir({
          "index.html": file("<!doctype html><h1>It works</h1>\n"),
        }),
      }),
    }),
    tmp: dir({}),
  });
}

function simRoot(serverId: string): SimNode {
  let node = simStore.get(serverId);
  if (!node) {
    node = seedSim();
    simStore.set(serverId, node);
  }
  return node;
}

/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
  if (!rights) return null;
  const bits = (s: string): number =>
    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
}

function splitPath(p: string): string[] {
  return p.split("/").filter((s) => s.length > 0);
}

function simResolve(serverId: string, p: string): SimNode | null {
  let node = simRoot(serverId);
  for (const part of splitPath(p)) {
    if (node.type !== "dir") return null;
    const next = node.children[part];
    if (!next) return null;
    node = next;
  }
  return node;
}

function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
  const parts = splitPath(p);
  if (parts.length === 0) return null;
  const name = parts[parts.length - 1];
  const parentPath = "/" + parts.slice(0, -1).join("/");
  const parent = simResolve(serverId, parentPath);
  if (!parent || parent.type !== "dir") return null;
  return { parent, name };
}

// ----------------------------------------------------------------------------
// Typed operations (sandbox-aware)
// ----------------------------------------------------------------------------

export async function listDir(server: SftpServer, path: string, opts?: { poolKey?: string }): Promise<SftpEntry[]> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such directory.");
    if (node.type !== "dir") throw new Error("Not a directory.");
    return Object.entries(node.children)
      .map(([name, child]) => ({
        name,
        type: child.type === "dir" ? "d" : "-",
        isDirectory: child.type === "dir",
        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
        modifiedMs: child.mtime,
        mode: child.mode,
      }))
      .sort((a, b) =>
        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
      );
  }

  return withSftp(server, async (client) => {
    const list = await client.list(path);
    return list
      .map((e) => ({
        name: e.name,
        type: e.type,
        isDirectory: e.type === "d",
        size: e.size,
        modifiedMs: e.modifyTime,
        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
        // mode — derive the octal permission bits from them.
        mode: rightsToMode(e.rights),
      }))
      .sort((a, b) =>
        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
      );
  }, opts);
}

/**
 * List `path`, or — when it does not exist (or is not a folder) — its nearest existing parent,
 * in ONE connection (the browser used to probe parents one request, and one SSH handshake, at a
 * time). Returns the path actually listed. Parents are derived by trimming segments off the
 * already-normalised `path`, so they need no further validation. Any other failure (permission,
 * connection) is thrown, not walked past.
 */
export async function listNearestDir(
  server: SftpServer,
  path: string,
  opts?: { poolKey?: string }
): Promise<{ path: string; entries: SftpEntry[]; fellBack: boolean }> {
  let cur = path;
  for (let i = 0; i < 64; i++) {
    try {
      return { path: cur, entries: await listDir(server, cur, opts), fellBack: cur !== path };
    } catch (e) {
      const m = e instanceof Error ? e.message : String(e);
      if (cur === "/" || !/no such|not a directory/i.test(m)) throw e;
      const up = cur.slice(0, cur.lastIndexOf("/"));
      cur = up === "" ? "/" : up;
    }
  }
  throw new Error("No such directory.");
}

export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file or directory.");
    return {
      isDirectory: node.type === "dir",
      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
      modifiedMs: node.mtime,
      mode: node.mode,
    };
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    return {
      isDirectory: s.isDirectory,
      size: s.size,
      modifiedMs: s.modifyTime,
      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
    };
  });
}

/**
 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
 * the cap so we never buffer an unbounded file into memory / the editor.
 */
export async function readFileText(
  server: SftpServer,
  path: string,
  maxBytes: number,
  opts?: { poolKey?: string }
): Promise<string> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Not a file.");
    if (Buffer.byteLength(node.content) > maxBytes) {
      throw new Error("File is too large to edit in the browser.");
    }
    return node.content;
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Not a file.");
    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
    const buf = (await client.get(path)) as Buffer;
    return buf.toString("utf8");
  }, opts);
}

export async function writeFileText(
  server: SftpServer,
  path: string,
  content: string
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content,
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(Buffer.from(content, "utf8"), path);
  });
}

export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    return;
  }

  await withSftp(server, async (client) => {
    await client.mkdir(path, false);
  });
}

export async function renamePath(
  server: SftpServer,
  from: string,
  to: string
): Promise<void> {
  if (SANDBOX) {
    const src = simResolve(server.id, from);
    if (!src) throw new Error("No such file or directory.");
    const dst = simParent(server.id, to);
    if (!dst) throw new Error("Invalid destination.");
    if (dst.parent.children[dst.name]) {
      throw new Error("A file or folder with that name already exists.");
    }
    const srcLoc = simParent(server.id, from);
    if (!srcLoc) throw new Error("Cannot rename the root.");
    delete srcLoc.parent.children[srcLoc.name];
    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
    return;
  }

  await withSftp(server, async (client) => {
    await client.rename(from, to);
  });
}

/** Remove a file, or recursively remove a directory. */
export async function removePath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Cannot remove the root.");
    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
    delete loc.parent.children[loc.name];
    return;
  }

  await withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) {
      await client.rmdir(path, true); // recursive
    } else {
      await client.delete(path);
    }
  });
}

export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file or directory.");
    node.mode = mode & 0o777;
    return;
  }

  await withSftp(server, async (client) => {
    await client.chmod(path, mode & 0o777);
  });
}

// ----------------------------------------------------------------------------
// Streaming helpers for the upload/download route
// ----------------------------------------------------------------------------

/** Read an entire file into a Buffer (used by the download endpoint). */
export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Not a file.");
    return Buffer.from(node.content, "utf8");
  }

  return withSftp(server, async (client) => {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Not a file.");
    return (await client.get(path)) as Buffer;
  });
}

/** Write a Buffer to a path (used by the upload endpoint). */
export async function writeFileBuffer(
  server: SftpServer,
  path: string,
  data: Buffer
): Promise<void> {
  if (SANDBOX) {
    const loc = simParent(server.id, path);
    if (!loc) throw new Error("Invalid path.");
    const existing = loc.parent.children[loc.name];
    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
    loc.parent.children[loc.name] = {
      type: "file",
      mtime: Date.now(),
      mode: existing?.type === "file" ? existing.mode : 0o644,
      content: data.toString("utf8"),
    };
    return;
  }

  await withSftp(server, async (client) => {
    await client.put(data, path);
  });
}

/**
 * `mkdir -p`: create `path` and any missing parents; a no-op when it already
 * exists as a directory. Used by folder uploads. Callers pass an already
 * validated absolute path.
 */
export async function mkdirpPath(server: SftpServer, path: string): Promise<void> {
  if (SANDBOX) {
    let cur = "";
    for (const seg of splitPath(path)) {
      cur += "/" + seg;
      const node = simResolve(server.id, cur);
      if (node) {
        if (node.type !== "dir") throw new Error("A file with that name already exists.");
        continue;
      }
      const loc = simParent(server.id, cur);
      if (!loc) throw new Error("Invalid path.");
      loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
    }
    return;
  }

  await withSftp(server, async (client) => {
    // ssh2-sftp-client's recursive mkdir stats each level and only creates
    // what is missing; it rejects if a level exists as a non-directory.
    await client.mkdir(path, true);
  });
}

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { parseRelPath } from "@/lib/upload-paths";
import {
  readFileBuffer,
  writeFileBuffer,
  mkdirPath,
  mkdirpPath,
  normalizePath,
  validateName,
  joinPath,
  type SftpServer,
} from "@/lib/sftp";

/**
 * File download / upload endpoint for the in-portal file manager.
 *
 *   GET  /api/files/[serverId]?path=/abs/file&download=1   -> streams the file
 *   POST /api/files/[serverId]?path=/abs/dir               -> multipart upload
 *
 * Both are authenticated and ownership-checked (owner or admin), path-validated
 * (absolute, no `..`), size-capped, and rate-limited. Real SFTP in production;
 * an in-memory simulation on the sandbox (handled inside lib/sftp).
 */
export const dynamic = "force-dynamic";

/** Max upload size accepted per request. */
const MAX_UPLOAD_BYTES = 250 * 1024 * 1024; // 250 MB

/**
 * Folder uploads send one request per file (plus one per empty directory), so
 * the old flat 30/min cap blocked any real mod folder. The request cap is now
 * generous, and abuse is bounded by the two limits that actually cost us
 * something: bytes per minute per user, and concurrent in-flight uploads per
 * user (each opens its own SFTP connection to the customer's VM).
 */
const UPLOAD_REQ_PER_MIN = 1200;
const UPLOAD_BYTES_PER_MIN = 2 * 1024 * 1024 * 1024; // 2 GB
const UPLOAD_MAX_CONCURRENT = 6;

const g = globalThis as unknown as {
  __nxFilesBytes?: Map<string, { t: number; n: number }[]>;
  __nxFilesInflight?: Map<string, number>;
};
const byteLog: Map<string, { t: number; n: number }[]> = (g.__nxFilesBytes ??= new Map());
const inflight: Map<string, number> = (g.__nxFilesInflight ??= new Map());

/** Record `n` bytes for a user; false when that would exceed the per-minute budget. */
function takeBytes(userId: string, n: number): boolean {
  const now = Date.now();
  const log = (byteLog.get(userId) ?? []).filter((x) => now - x.t < 60_000);
  const used = log.reduce((a, x) => a + x.n, 0);
  if (used + n > UPLOAD_BYTES_PER_MIN) { byteLog.set(userId, log); return false; }
  log.push({ t: now, n });
  byteLog.set(userId, log);
  return true;
}

async function ownedServer(
  serverId: string,
  userId: string,
  isAdmin: boolean
): Promise<SftpServer | null> {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      rootPassword: true,
      // The encrypted-at-rest password is the authoritative one for any server
      // provisioned after credential encryption shipped; the plaintext column is
      // null for those. serverRootPassword() prefers Enc and falls back to
      // plaintext, so BOTH must be selected — omitting Enc made every
      // encrypted-password server fail with "Server has no root password set."
      rootPasswordEnc: true, sshManagementKeyEnc: true,
      sshPort: true,
      // connectionTarget() dials dedicated-IP servers on guestSshPort (default 22);
      // without selecting it a non-22 guest sshd was unreachable for uploads.
      guestSshPort: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true } },
    },
  });
  if (!server) return null;
  if (server.userId !== userId && !isAdmin) return null;
  return server;
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:download:${user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let path: string;
  try {
    path = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }
  if (path === "/") return NextResponse.json({ error: "not a file" }, { status: 400 });

  let data: Buffer;
  try {
    data = await readFileBuffer(server, path);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "read failed";
    const status = /No such|Not a file/i.test(msg) ? 404 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  const filename = path.split("/").pop() || "download";
  // Always force a download to avoid the browser rendering server content inline.
  return new NextResponse(data as unknown as BodyInit, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(data.length),
      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
      "Cache-Control": "private, no-store",
    },
  });
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:upload:${user.id}`, { max: UPLOAD_REQ_PER_MIN, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let dir: string;
  try {
    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }

  if ((inflight.get(user.id) ?? 0) >= UPLOAD_MAX_CONCURRENT) {
    return NextResponse.json(
      { error: "too many uploads in flight — slow down", retryAfterSec: 2 },
      { status: 429, headers: { "Retry-After": "2" } }
    );
  }
  inflight.set(user.id, (inflight.get(user.id) ?? 0) + 1);
  try {
    return await handleUpload(req, server, user.id, dir);
  } finally {
    const n = (inflight.get(user.id) ?? 1) - 1;
    if (n <= 0) inflight.delete(user.id); else inflight.set(user.id, n);
  }
}

async function handleUpload(
  req: NextRequest,
  server: SftpServer,
  userId: string,
  dir: string
): Promise<NextResponse> {
  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
  }

  // Folder uploads: `relPath` is the path of the file (or, with `mkdir=1`, the
  // empty directory) relative to `dir`, e.g. "ModLib/lib/a.jar". Validated by
  // the same parseRelPath the browser uses, then re-normalized under `dir`.
  const relRaw = form.get("relPath");
  const mkdirOnly = form.get("mkdir") === "1";
  let relSegs: string[] = [];
  if (relRaw !== null && relRaw !== "") {
    try {
      relSegs = parseRelPath(relRaw, mkdirOnly ? "dir" : "file");
    } catch (err) {
      return NextResponse.json(
        { error: err instanceof Error ? err.message : "invalid path" },
        { status: 400 }
      );
    }
  } else if (mkdirOnly) {
    return NextResponse.json({ error: "a relative path is required" }, { status: 400 });
  }

  if (mkdirOnly) {
    try {
      const target = joinPath(dir, relSegs.join("/"));
      await mkdirpPath(server, target);
      return NextResponse.json({ ok: true, path: target });
    } catch (err) {
      const msg = err instanceof Error ? err.message : "mkdir failed";
      return NextResponse.json({ error: msg }, { status: /Invalid|exists/i.test(msg) ? 400 : 502 });
    }
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "no file provided" }, { status: 400 });
  }
  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json(
      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
      { status: 413 }
    );
  }
  if (!takeBytes(userId, file.size)) {
    return NextResponse.json(
      { error: "upload volume limit reached — wait a minute and retry", retryAfterSec: 30 },
      { status: 429, headers: { "Retry-After": "30" } }
    );
  }

  let target: string;
  let targetDir = dir;
  try {
    if (relSegs.length > 0) {
      const name = validateName(relSegs[relSegs.length - 1]);
      targetDir = joinPath(dir, relSegs.slice(0, -1).join("/"));
      target = joinPath(targetDir, name);
    } else {
      const name = validateName((file.name || "upload").trim());
      target = joinPath(dir, name);
    }
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid filename" },
      { status: 400 }
    );
  }

  try {
    const data = Buffer.from(await file.arrayBuffer());
    // Re-check the actual byte length in case the reported size was understated.
    if (data.length > MAX_UPLOAD_BYTES) {
      return NextResponse.json({ error: "file too large" }, { status: 413 });
    }
    // Create the destination directory (and, for folder uploads, any missing
    // parents — mkdir -p). The file manager normally targets an existing dir
    // (harmless no-op), but the Matrix console uploads into ~/nxeon-uploads,
    // which may not exist yet, and client.put() does not create parent dirs.
    try {
      if (relSegs.length > 1) await mkdirpPath(server, targetDir);
      else await mkdirPath(server, dir);
    } catch {
      /* already exists / benign — the write below surfaces any real failure */
    }
    await writeFileBuffer(server, target, data);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "upload failed";
    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  return NextResponse.json({ ok: true, path: target });
}
/**
 * A tiny keyed connection pool with an idle timeout, used by lib/sftp.ts for READ operations
 * (list, read) so that browsing folders does not pay an SSH handshake (~150-350 ms measured) on
 * every click.
 *
 * SECURITY MODEL (the reason it is shaped this way):
 *  - The pool is only reached from server code AFTER the caller's session, ownership and path
 *    validation have been checked on every single call (lib/actions-files.ts). The pool saves the
 *    TCP/SSH handshake and nothing else: it never skips an authorisation check.
 *  - The key embeds the authenticated USER id, the server id, the connection target and a
 *    fingerprint of the credential, so a connection opened for user A is never handed to user B,
 *    never reused for another server, and is abandoned when the credential rotates.
 *  - Connections idle out (default 25 s), are capped in number (oldest idle evicted), are closed on
 *    any 'close'/'error' event, and are dropped on a connection-type error (never reused after one).
 *  - Operations on one connection are serialised, so two requests never interleave on a channel.
 *
 * Generic over the client type and free of I/O imports so the keying/expiry logic is unit-tested
 * with fake timers and a fake client (test/sftp-pool.test.ts).
 */
export type PoolOpts<C> = {
  idleMs?: number;
  maxEntries?: number;
  close: (c: C) => Promise<void> | void;
};

type Entry<C> = { conn: C; timer: ReturnType<typeof setTimeout> | null; queue: Promise<unknown>; lastUsed: number; uses: number };

export class ConnPool<C> {
  private entries = new Map<string, Entry<C>>();
  private pending = new Map<string, Promise<Entry<C>>>();
  constructor(private opts: PoolOpts<C>) {}

  get size() { return this.entries.size; }
  has(key: string) { return this.entries.has(key); }

  private idleMs() { return this.opts.idleMs ?? 25_000; }

  private arm(key: string, e: Entry<C>) {
    if (e.timer) clearTimeout(e.timer);
    e.timer = setTimeout(() => this.evict(key, e), this.idleMs());
    (e.timer as { unref?: () => void }).unref?.();
  }

  /** Close and forget an entry (only if it is still the registered one). */
  evict(key: string, only?: Entry<C>) {
    const e = this.entries.get(key);
    if (!e || (only && e !== only)) return;
    this.entries.delete(key);
    if (e.timer) clearTimeout(e.timer);
    try { void Promise.resolve(this.opts.close(e.conn)).catch(() => {}); } catch { /* best effort */ }
  }

  /** Mark a connection dead from outside (the client's own 'close'/'error' event). */
  drop(key: string, conn: C) {
    const e = this.entries.get(key);
    if (e && e.conn === conn) this.evict(key, e);
  }

  closeAll() { for (const k of [...this.entries.keys()]) this.evict(k); }

  private async acquire(key: string, connect: () => Promise<C>): Promise<{ e: Entry<C>; reused: boolean }> {
    const existing = this.entries.get(key);
    if (existing) return { e: existing, reused: true };
    let p = this.pending.get(key);
    if (!p) {
      p = connect().then((conn) => {
        const e: Entry<C> = { conn, timer: null, queue: Promise.resolve(), lastUsed: Date.now(), uses: 0 };
        this.entries.set(key, e);
        this.trim(key);
        return e;
      }).finally(() => { this.pending.delete(key); });
      this.pending.set(key, p);
    }
    return { e: await p, reused: false };
  }

  private trim(keep: string) {
    const max = this.opts.maxEntries ?? 32;
    while (this.entries.size > max) {
      let oldestKey: string | null = null; let oldest = Infinity;
      for (const [k, v] of this.entries) if (k !== keep && v.lastUsed < oldest) { oldest = v.lastUsed; oldestKey = k; }
      if (oldestKey === null) break;
      this.evict(oldestKey);
    }
  }

  /**
   * Run `fn` on the pooled connection for `key`, opening one with `connect` when there is none.
   * A connection-type failure on a REUSED connection is retried once on a fresh one.
   */
  async run<T>(key: string, connect: () => Promise<C>, fn: (c: C) => Promise<T>, isConnError: (e: unknown) => boolean): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      const { e, reused } = await this.acquire(key, connect);
      if (e.timer) { clearTimeout(e.timer); e.timer = null; } // never idle-close mid-operation
      const job = e.queue.then(() => fn(e.conn));
      e.queue = job.catch(() => undefined);
      try {
        const out = await job;
        e.uses++; e.lastUsed = Date.now();
        if (this.entries.get(key) === e) this.arm(key, e);
        return out;
      } catch (err) {
        if (isConnError(err)) {
          this.evict(key, e);
          if (reused && attempt === 0) continue;
        } else if (this.entries.get(key) === e) {
          e.lastUsed = Date.now(); this.arm(key, e);
        }
        throw err;
      }
    }
  }
}

/** Errors that mean "this connection is unusable", as opposed to a normal SFTP answer such as "No such file". */
export function isConnectionError(e: unknown): boolean {
  const m = e instanceof Error ? e.message : String(e);
  if (/no such|permission denied|not a directory|is a directory|failure/i.test(m)) return false;
  return /not connected|no sftp connection|econnreset|epipe|econnrefused|etimedout|timed out|channel (is )?closed|connection (lost|closed|ended)|socket|handshake|ended|\bend\b/i.test(m);
}
