 *     at the client, and never exposes another user's server.
 *
 * The heavy lifting (real SFTP vs. sandbox simulation) lives in lib/sftp.ts.
 */
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import type { FileEntry, ExtractResult } from "./files-types";
import { SANDBOX } from "./sandbox";
import {
  withServerSsh, execInput, exec, shellQuote, pkgInstallPrefix, QUICK_TIMEOUT_MS,
} from "./ssh-exec";
import {
