/** One extraction at a time per server: two concurrent unpacks could jointly fill the disk. */
const extracting = new Set<string>();

/**
 * Extract an archive that is already on the server, ON the server, over SSH.
 *
 * SECURITY (see lib/archive-extract.ts for the layered design): ownership is
 * checked by `ownedServer` before any credential is touched; both paths are
 * normalised (no `..`, absolute, no control chars, not under /proc /sys /dev)
 * and every argument reaches the guest as a shell-quoted positional parameter of
 * a fixed script — nothing user-controlled is ever interpolated into shell code.
 * It runs as the same user the file manager already operates as (root on the
 * customer's own VM), never anything more privileged. The archive is listed and
 * checked BEFORE it is unpacked; limits: ${MAX_EXTRACT_BYTES / 1024 ** 3} GiB,
 * ${MAX_EXTRACT_FILES} entries, ${EXTRACT_TIMEOUT_S}s, free-disk margin.
 *
 * Paths here deliberately are NOT held to PATH_RE (`[A-Za-z0-9._/-]`): customers
 * name mod zips "My Mod (1).zip", and a quoting-safe positional-arg design makes
 * the stricter allow-list unnecessary.
 */
export async function extractArchive(
  serverId: string,
  path: string,
  targetDir: string,
  overwrite: boolean
): Promise<ExtractResult> {
  let lockKey: string | null = null;
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "extract", 8);
    if (limited) return { ok: false, error: limited };

    const archive = checkGuestPath(normalizePath(path), "archive path");
    const target = checkGuestPath(normalizePath(targetDir || "/"), "target folder");
    if (target === "/") return { ok: false, error: "Choose a folder to extract into — extracting straight into / is not allowed." };
    const info = detectArchive(archive);
    if (!info) {
      return { ok: false, error: "Unsupported archive type. Supported: .zip, .tar, .tar.gz/.tgz, .tar.bz2, .tar.xz, .7z and .rar." };
    }
    if (SANDBOX) return { ok: false, error: "Extraction isn't available in the sandbox preview." };
    if (extracting.has(serverId)) return { ok: false, error: "An extraction is already running on this server — wait for it to finish." };
    extracting.add(serverId);
    lockKey = serverId;

    const run = (conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], timeoutMs: number, ...args: string[]) =>
      execInput(conn, `bash -s -- ${args.map(shellQuote).join(" ")}`, GUEST_SCRIPT, timeoutMs);

    const res = await withServerSsh(server, async (conn): Promise<ExtractResult> => {
      let probe = parseProbe((await run(conn, QUICK_TIMEOUT_MS, "probe", archive, target)).stdout);
      if (!probe.archiveOk) return { ok: false, error: "That archive could not be found on the server." };
      if (probe.targetNotDir) return { ok: false, error: "The target is a file, not a folder." };

      // Install any missing tool via the platform's package helper.
      const installed: string[] = [];
      const missing = requiredTools(info).filter((t) => !probe.tools[t]);
      if (missing.length) {
        let prefix: string;
        try {
          prefix = await pkgInstallPrefix(conn);
        } catch {
          return { ok: false, error: `This server is missing ${missing.join(", ")} and has no supported package manager to install it. Install it from the console, then try again.` };
        }
        const pm = pmFromPrefix(prefix);
        const pkgs = [...new Set(missing.map((t) => packageFor(pm, t)))];
        if (pkgs.some((p) => p === null)) {
          return { ok: false, error: `This server is missing ${missing.join(", ")}, which can't be installed automatically.` };
        }
        const list = (pkgs as string[]).join(" ");
        const cmd = pm === "apt"
          ? `${prefix} ${list} >/dev/null 2>&1 || (apt-get update -qq >/dev/null 2>&1 && ${prefix} ${list} >/dev/null 2>&1)`
          : `${prefix} ${list} >/dev/null 2>&1`;
        const inst = await withInstallTimeout(conn, cmd);
        probe = parseProbe((await run(conn, QUICK_TIMEOUT_MS, "probe", archive, target)).stdout);
        const still = requiredTools(info).filter((t) => !probe.tools[t]);
        if (!inst || still.length) {
          return { ok: false, error: `This server is missing ${still.join(", ") || missing.join(", ")} and it could not be installed automatically (is the server online and able to reach its package mirror?). Install it from the console, then try again.` };
        }
        installed.push(...pkgs as string[]);
      }

      // List + check BEFORE unpacking anything.
      const fam = toolFamily(info.kind);
      const listed = parseListOutput((await run(conn, 120_000, "list", fam, archive)).stdout);
      if (listed.truncated) return { ok: false, error: "This archive has too many entries to extract safely." };
      if (listed.rc !== 0) return { ok: false, error: "Couldn't read this archive — it may be damaged, encrypted, or an unsupported variant." };
      let entries;
      try {
        entries = parseListing(info.kind, listed.text);
      } catch (e) {
        return { ok: false, error: e instanceof Error ? e.message : "Couldn't read this archive." };
      }
      const chk = checkListing(entries, { kind: info.kind, archiveBytes: probe.archiveBytes, availBytes: probe.availBytes });
      if (!chk.ok) return { ok: false, error: chk.error };

      const out = await run(
        conn, (EXTRACT_TIMEOUT_S + 60) * 1000,
        "extract", fam, archive, target, overwrite ? "1" : "0",
        String(MAX_EXTRACT_BYTES), String(MAX_EXTRACT_FILES), String(EXTRACT_TIMEOUT_S)
      );
      const parsed = parseExtractOutput(out.stdout);
      if (!parsed.ok) return parsed;
      return {
        ok: true, target, extracted: parsed.extracted, skippedExisting: parsed.skippedExisting,
        skippedUnsafe: parsed.skippedUnsafe, bytes: parsed.bytes, installed,
      };
    });

    await db.auditLog.create({
      data: {
        userId: user.id,
        action: "files.extract",
        detail: res.ok
          ? `${serverId} ${archive} -> ${target} (${res.extracted} files, ${res.skippedExisting + res.skippedUnsafe} skipped${overwrite ? ", overwrite" : ""})`.slice(0, 500)
          : `${serverId} ${archive} -> ${target} FAILED: ${res.error}`.slice(0, 500),
      },
    }).catch(() => {});
    return res;
  } catch (err) {
    return { ok: false, error: safeError(err) };
  } finally {
    if (lockKey) extracting.delete(lockKey);
  }
}

/** Run a fixed package-install command with a 5-minute cap; true on success. */
async function withInstallTimeout(
  conn: Parameters<Parameters<typeof withServerSsh>[1]>[0],
  cmd: string
): Promise<boolean> {
  try {
    const r = await exec(conn, cmd, 5 * 60_000);
    return r.code === 0;
  } catch {
    return false;
  }
}
