 * means members are stored by their bare names (no leading path). Exit 1 ("a file changed while we
 * read it") is tolerated by the caller; >= 2 aborts the stream. `nice` is used when present so a big
 * download does not starve the customer's own game server; the compressor is the fast level.
 */
export function archiveCommand(dir: string, names: string[]): string {
  const members = names.map(shellQuote).join(" ");
  return (
    `N=; command -v nice >/dev/null 2>&1 && N='nice -n 10'; ` +
    `exec $N tar -c --ignore-failed-read --use-compress-program='gzip -1' -f - -C ${shellQuote(dir)} -- ${members}`
  );
}

/**
 * Pre-flight: counts entries and sums regular-file bytes WITHOUT archiving, stopping early past the
 * caps. Prints `OK <entries> <bytes>`, `OVER <entries> <bytes>`, `NOTAR`, or `NODIR`. `find` gets
 * `./name` operands (a name starting with "-" can never be an option). Needs GNU find (-printf); on
 * a guest without it the output is empty and the caller falls back to the streaming byte cap.
 */
export function preflightCommand(dir: string, names: string[], maxEntries = MAX_ARCHIVE_ENTRIES, maxBytes = MAX_ARCHIVE_BYTES): string {
  const operands = names.map((n) => shellQuote("./" + n)).join(" ");
  const caps = `${Math.trunc(maxEntries)} ${Math.trunc(maxBytes)}`; // numbers only, never user text
  return (
    `command -v tar >/dev/null 2>&1 || { echo NOTAR; exit 0; }; ` +
    `cd -- ${shellQuote(dir)} 2>/dev/null || { echo NODIR; exit 0; }; ` +
    `find -P ${operands} -printf '%y %s\\n' 2>/dev/null | awk -v caps='${caps}' ` +
    `'BEGIN{split(caps,c," ")} {n++; if($1=="f")b+=$2; if(n>c[1]||b>c[2]){print "OVER",n,b; over=1; exit}} ` +
    `END{if(!over)print "OK",n+0,b+0}'`
  );
}

export type Preflight =
  | { kind: "ok"; entries: number; bytes: number }
  | { kind: "over"; entries: number; bytes: number }
  | { kind: "notar" }
  | { kind: "nodir" }
  | { kind: "unknown" };

export function parsePreflight(out: string): Preflight {
  const line = String(out).trim().split("\n").pop()?.trim() ?? "";
  if (line === "NOTAR") return { kind: "notar" };
  if (line === "NODIR") return { kind: "nodir" };
  const m = /^(OK|OVER) (\d+) (\d+)$/.exec(line);
  if (!m) return { kind: "unknown" };
  return { kind: m[1] === "OK" ? "ok" : "over", entries: Number(m[2]), bytes: Number(m[3]) };
}

/** Customer-facing sentence for a pre-flight verdict, or null when the archive may proceed. */
export function preflightProblem(p: Preflight): string | null {
  switch (p.kind) {
    case "notar": return "This server doesn't have tar installed, so it can't build an archive. Install it from the console (for example apt install tar), then try again.";
    case "nodir": return "That folder no longer exists on the server.";
    case "over":
      return p.entries > MAX_ARCHIVE_ENTRIES
        ? `That selection has more than ${MAX_ARCHIVE_ENTRIES.toLocaleString("en-US")} files. Download smaller folders one at a time, or use SFTP for the whole thing.`
        : `That selection is larger than ${fmtBytesShort(MAX_ARCHIVE_BYTES)}. Download smaller folders one at a time, or use SFTP for the whole thing.`;
    default: return null;
  }
}

// ---- stream guard ---------------------------------------------------------

/**
 * Pass-through that counts bytes, aborts the stream when it exceeds `maxBytes` (the backstop for
 * archives whose pre-flight could not run, and for a lying size), and aborts when no bytes arrive
 * for `idleMs`. Back-pressure is preserved (a plain Transform). `onBytes` receives the running total.
 */
export function createGuard(opts: { maxBytes: number; idleMs?: number; onBytes?: (total: number) => void }): Transform & { total: number } {
  let total = 0;
  let timer: ReturnType<typeof setTimeout> | null = null;
  const idleMs = opts.idleMs ?? DOWNLOAD_IDLE_MS;
  const arm = () => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => t.destroy(new Error("Download stalled — the server stopped sending data.")), idleMs);
    (timer as { unref?: () => void }).unref?.();
  };
  const t = new Transform({
    transform(chunk: Buffer, _enc, cb) {
      total += chunk.length;
      (t as unknown as { total: number }).total = total;
      opts.onBytes?.(total);
      if (total > opts.maxBytes) return cb(new Error(`Download exceeded the ${fmtBytesShort(opts.maxBytes)} limit and was stopped.`));
      arm();
      cb(null, chunk);
    },
    flush(cb) { if (timer) clearTimeout(timer); cb(); },
    destroy(err, cb) { if (timer) clearTimeout(timer); cb(err); },
  }) as Transform & { total: number };
  t.total = 0;
  arm();
  return t;
}

// ---- pre-check tokens -----------------------------------------------------

/**
 * The UI pre-checks an archive (to show a clear message instead of a dead download) and then starts
 * the real download. A pre-check result is remembered for 90 s, bound to the exact user + server +
 * dir + names, so the real request does not walk a huge folder twice. A token is single-use. It only
 * ever SKIPS the pre-flight walk; the streaming byte cap still applies, and every auth / ownership
 * check still runs on the real request.
 */
export class PrecheckTokens {
  private m = new Map<string, { bind: string; at: number }>();
  constructor(private ttlMs = 90_000, private max = 500, private now: () => number = Date.now) {}
  private static bindKey(userId: string, serverId: string, dir: string, names: string[]) {
    return JSON.stringify([userId, serverId, dir, [...names].sort()]);
  }
  issue(userId: string, serverId: string, dir: string, names: string[]): string {
    const t = randomBytes(16).toString("hex");
    this.m.set(t, { bind: PrecheckTokens.bindKey(userId, serverId, dir, names), at: this.now() });
    while (this.m.size > this.max) this.m.delete(this.m.keys().next().value as string);
    return t;
  }
  consume(token: string | null | undefined, userId: string, serverId: string, dir: string, names: string[]): boolean {
    if (!token) return false;
    const v = this.m.get(token);
    this.m.delete(token);
    if (!v || this.now() - v.at > this.ttlMs) return false;
    return v.bind === PrecheckTokens.bindKey(userId, serverId, dir, names);
  }
}

/** Who may download: the owner, or an admin. Pure so the rule is unit-tested; the route applies it and answers 404 (never 403) so existence is not leaked. */
export function mayAccessServer(server: { userId: string } | null, userId: string, isAdmin: boolean): boolean {
  return !!server && (server.userId === userId || isAdmin);
}

