// ----------------------------------------------------------------------------
// Streaming download (Files tab). Never buffers the file: bytes flow SFTP -> response with
// back-pressure, on a connection owned by this one download.
// ----------------------------------------------------------------------------

export type DownloadHandle = {
  size: number;
  modifiedMs: number;
  /** Open the byte stream for an inclusive range (whole file when omitted). */
  open(range?: { start: number; end: number }): Readable;
  /** Close the underlying connection. Idempotent; also happens automatically when the stream closes. */
  close(): Promise<void>;
};

/**
 * Stat `path` and, if it is a REGULAR file (not a directory, device node or fifo), return a handle
 * that streams it. Uses its own non-pooled connection: a pooled one would hold the user's browsing
 * connection busy for the whole transfer (the pool serialises operations). Throws user-safe errors
 * ("No such file.", "Not a file.", "Is a folder.").
 */
export async function openDownload(server: SftpServer, path: string): Promise<DownloadHandle> {
  if (SANDBOX) {
    const node = simResolve(server.id, path);
    if (!node) throw new Error("No such file.");
    if (node.type !== "file") throw new Error("Is a folder.");
    const buf = Buffer.from(node.content, "utf8");
    return {
      size: buf.length,
      modifiedMs: node.mtime,
      open: (r) => Readable.from([r ? buf.subarray(r.start, r.end + 1) : buf]),
      close: async () => {},
    };
  }
  const target = connectionTarget(server);
  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
  const privateKey = serverManagementKey(server);
  const password = serverRootPassword(server);
  if (!privateKey && !password) throw new Error("Server has no root password set.");

  const client = await connectSftp(target, privateKey, password);
  let closed = false;
  const close = async () => {
    if (closed) return;
    closed = true;
    try { await client.end(); } catch { /* best effort */ }
  };
  try {
    const s = await client.stat(path);
    if (s.isDirectory) throw new Error("Is a folder.");
    if (!s.isFile) throw new Error("Not a file.");
    const sftp = (client as unknown as { sftp: { createReadStream(p: string, o?: Record<string, unknown>): Readable } }).sftp;
    return {
      size: s.size,
      modifiedMs: s.modifyTime,
      open(range) {
        const st = sftp.createReadStream(path, { ...(range ? { start: range.start, end: range.end } : {}), highWaterMark: 256 * 1024 });
        st.once("close", () => { void close(); });
        return st;
      },
      close,
    };
  } catch (e) {
    await close();
    throw e;
  }
}

/**
 * SANDBOX ONLY: copy the simulated entries `names` of `dir` into the real local directory `dest`
 * (a fresh temp dir the caller owns), so the sandbox can exercise the real `tar` pipeline.
 */
export async function simSnapshotTo(
  serverId: string,
  dir: string,
  names: string[],
  dest: string
): Promise<void> {
  if (!SANDBOX) throw new Error("simSnapshotTo is sandbox-only");
  const { mkdir, writeFile } = await import("node:fs/promises");
  const nodePath = await import("node:path");
  const walk = async (node: SimNode, out: string) => {
    if (node.type === "file") { await writeFile(out, node.content); return; }
    await mkdir(out, { recursive: true });
    for (const [n, child] of Object.entries(node.children)) await walk(child, nodePath.join(out, n));
  };
  const base = simResolve(serverId, dir);
  if (!base || base.type !== "dir") throw new Error("That folder no longer exists on the server.");
  for (const n of names) {
    const child = base.children[n];
    if (!child) throw new Error("No such file or folder.");
    await walk(child, nodePath.join(dest, n));
  }
}
