/**
 * Streamed folder / multi-select download for the Files tab: `tar | gzip` runs ON the guest over
 * the existing SSH exec channel and its stdout is piped straight into the HTTP response. Nothing is
 * written to the guest's disk (no temp archive) or to ours, and nothing is buffered: the SSH channel
 * window gives back-pressure, so a slow browser slows tar down rather than filling memory.
 *
 * Why tar.gz and not zip: `tar` and `gzip` ship on every mainstream guest image, whereas `zip` does
 * not, and installing a package on a customer's VM as a side effect of a download is not acceptable.
 * Why on the guest and not an SFTP walk: one stream instead of thousands of round trips per file.
 *
 * The command strings are built by the pure, tested helpers in lib/files-download.ts; every
 * user-controlled value is shell-quoted there. Plain server module (not "use server").
 */
import { Readable, PassThrough } from "node:stream";
import { spawn } from "node:child_process";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { Client } from "ssh2";
import { SANDBOX } from "./sandbox";
import { exec, withServerSsh } from "./ssh-exec";
import { simSnapshotTo, type SftpServer } from "./sftp";
import {
  archiveCommand, preflightCommand, parsePreflight, preflightProblem, MAX_ARCHIVE_BYTES, type Preflight,
} from "./files-download";

const PREFLIGHT_TIMEOUT_MS = 90_000;

export class ArchiveRefused extends Error {}

/** Walk the selection on the guest (read-only) and report entries / bytes against the caps. */
async function runPreflight(conn: Client, dir: string, names: string[]): Promise<Preflight> {
  try {
    const r = await exec(conn, preflightCommand(dir, names), PREFLIGHT_TIMEOUT_MS);
    return parsePreflight(r.stdout);
  } catch (e) {
    if (e instanceof Error && /timed out/i.test(e.message)) {
      throw new ArchiveRefused("That selection is too large to scan. Download smaller folders one at a time, or use SFTP for the whole thing.");
    }
    throw e;
  }
}

/** Pre-check only (no archive): `{entries, bytes}` when it may proceed, or throws ArchiveRefused with the customer-facing reason. */
export async function precheckArchive(
  server: SftpServer, dir: string, names: string[]
): Promise<{ entries: number | null; bytes: number | null }> {
  if (SANDBOX) return { entries: names.length, bytes: null };
  return withServerSsh(server, async (conn) => {
    const p = await runPreflight(conn, dir, names);
    const problem = preflightProblem(p);
    if (problem) throw new ArchiveRefused(problem);
    return p.kind === "ok" ? { entries: p.entries, bytes: p.bytes } : { entries: null, bytes: null };
  });
}

export type ArchiveStream = {
  stream: Readable;
  /** Tear everything down (client went away). Idempotent. */
  abort(): void;
  entries: number | null;
  bytes: number | null;
};

/**
 * Start the archive and resolve once bytes can flow. Rejects (ArchiveRefused for caps / missing tar)
 * BEFORE any response header is sent, so the route can still answer with a clean JSON error.
 * `skipPreflight` is set when a valid single-use pre-check token was presented. Failure AFTER the
 * stream started (tar exit >= 2, SSH drop) destroys the stream with an error, which resets the HTTP
 * connection, so the browser reports a FAILED download rather than saving a truncated archive as if
 * it were complete.
 */
export function startArchive(
  server: SftpServer, dir: string, names: string[], opts: { skipPreflight?: boolean } = {}
): Promise<ArchiveStream> {
  if (SANDBOX) return startSandboxArchive(server, dir, names);

  return new Promise<ArchiveStream>((resolveReady, rejectReady) => {
    let ready = false;
    void withServerSsh(server, (conn) => new Promise<void>((finished) => {
      void (async () => {
        let entries: number | null = null;
        let bytes: number | null = null;
        if (!opts.skipPreflight) {
          const p = await runPreflight(conn, dir, names);
          const problem = preflightProblem(p);
          if (problem) throw new ArchiveRefused(problem);
          if (p.kind === "ok") { entries = p.entries; bytes = p.bytes; }
        }
        conn.exec(archiveCommand(dir, names), (err, ch) => {
          if (err) { rejectReady(err); finished(); return; }
          const out = new PassThrough({ highWaterMark: 256 * 1024 });
          let stderr = "";
          // stderr MUST be drained or the SSH channel window stalls; keep a little for diagnostics only.
          ch.stderr.on("data", (d: Buffer) => { if (stderr.length < 2000) stderr += d.toString("utf8"); });
          let done = false;
          const end = () => { if (done) return; done = true; try { ch.close(); } catch { /* best effort */ } finished(); };
          ch.on("close", (code: number | null) => {
            // 0 = ok, 1 = "file changed as we read it" (a live game world): both are a usable archive.
            if (code === 0 || code === 1) out.end();
            else out.destroy(new Error(`The archive could not be completed (tar exited ${code ?? "abnormally"}).`));
            end();
          });
          ch.on("error", (e: Error) => { out.destroy(e); end(); });
          ch.pipe(out); // back-pressure: pipe pauses the channel while `out` is full
          out.once("close", end);
          ready = true;
          resolveReady({
            stream: out,
            abort: () => { out.destroy(); end(); },
            entries, bytes,
          });
        });
      })().catch((e) => { if (!ready) rejectReady(e); finished(); });
    })).catch((e) => { if (!ready) rejectReady(e); });
  });
}

/** Sandbox: materialise the simulated entries in a private temp dir and run the REAL tar on them. */
async function startSandboxArchive(server: SftpServer, dir: string, names: string[]): Promise<ArchiveStream> {
  const tmp = await mkdtemp(join(tmpdir(), "nx-dl-"));
  try {
    await simSnapshotTo(server.id, dir, names, tmp);
  } catch (e) {
    await rm(tmp, { recursive: true, force: true });
    throw new ArchiveRefused(e instanceof Error ? e.message : "Couldn't read that selection.");
  }
  const child = spawn("tar", ["-c", "-z", "-f", "-", "-C", tmp, "--", ...names], { stdio: ["ignore", "pipe", "ignore"] });
  const cleanup = () => { void rm(tmp, { recursive: true, force: true }); };
  child.once("close", cleanup);
  const out = child.stdout.pipe(new PassThrough());
  out.once("close", () => { child.kill(); cleanup(); });
  return { stream: out, abort: () => { out.destroy(); child.kill(); }, entries: names.length, bytes: null };
}

export { MAX_ARCHIVE_BYTES };

