          const problem = preflightProblem(p);
          if (problem) throw new ArchiveRefused(problem);
          if (p.kind === "ok") { entries = p.entries; bytes = p.bytes; }
        }
        conn.exec(archiveCommand(dir, names), (err, ch) => {
          if (err) { rejectReady(err); finished(); return; }
          const out = new PassThrough({ highWaterMark: 256 * 1024 });
          let stderr = "";
          // stderr MUST be drained or the SSH channel window stalls; keep a little for diagnostics only.
          ch.stderr.on("data", (d: Buffer) => { if (stderr.length < 2000) stderr += d.toString("utf8"); });
