            // 0 = ok, 1 = "file changed as we read it" (a live game world): both are a usable archive.
            if (code === 0 || code === 1) out.end();
            else out.destroy(new Error(`The archive could not be completed (tar exited ${code ?? "abnormally"}).`));
            end();
          });
          ch.on("error", (e: Error) => { out.destroy(e); end(); });
          ch.pipe(out); // back-pressure: pipe pauses the channel while `out` is full
          out.once("close", end);
          ready = true;
          resolveReady({
            stream: out,
            abort: () => { out.destroy(); end(); },
            entries, bytes,
          });
        });
      })().catch((e) => { if (!ready) rejectReady(e); finished(); });
    })).catch((e) => { if (!ready) rejectReady(e); });
  });
}

/** Sandbox: materialise the simulated entries in a private temp dir and run the REAL tar on them. */
async function startSandboxArchive(server: SftpServer, dir: string, names: string[]): Promise<ArchiveStream> {
  const tmp = await mkdtemp(join(tmpdir(), "nx-dl-"));
  try {
    await simSnapshotTo(server.id, dir, names, tmp);
  } catch (e) {
    await rm(tmp, { recursive: true, force: true });
    throw new ArchiveRefused(e instanceof Error ? e.message : "Couldn't read that selection.");
  }
  const child = spawn("tar", ["-c", "-z", "-f", "-", "-C", tmp, "--", ...names], { stdio: ["ignore", "pipe", "ignore"] });
  const cleanup = () => { void rm(tmp, { recursive: true, force: true }); };
  child.once("close", cleanup);
  const out = child.stdout.pipe(new PassThrough());
  out.once("close", () => { child.kill(); cleanup(); });
  return { stream: out, abort: () => { out.destroy(); child.kill(); }, entries: names.length, bytes: null };
}

