content.content:
// Download limits + a byte formatter. Import-free so BOTH the client file browser and the server
// route/helpers share one source of truth (lib/files-download.ts re-exports these).

/** Largest single file we stream (bytes). Larger files: clear 413 message, use SFTP. */
export const MAX_FILE_BYTES = 10 * 1024 ** 3; // 10 GiB
/** Largest archive, measured on the UNCOMPRESSED input before we start, and on the OUTPUT while streaming. */
export const MAX_ARCHIVE_BYTES = 4 * 1024 ** 3; // 4 GiB
/** Most files + folders + links one archive may contain. */
export const MAX_ARCHIVE_ENTRIES = 100_000;
/** Most top-level items in one multi-select download (keeps the URL short). */
export const MAX_ARCHIVE_ITEMS = 100;
/** Concurrent downloads per user: each one holds its own SSH connection to the customer's VM. */
export const MAX_CONCURRENT_DOWNLOADS = 3;
/** A stream with no bytes for this long is torn down (dead guest / stalled client). */
export const DOWNLOAD_IDLE_MS = 120_000;

export function fmtBytesShort(b: number): string {
  if (!(b > 0)) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(Math.floor(Math.log(b) / Math.log(1024)), u.length - 1);
  return `${(b / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${u[i]}`;
