"use client";

import { useCallback, useRef, useState } from "react";
import type { FileApi, FileEntry } from "@/lib/files-types";
import { MAX_ARCHIVE_ITEMS, MAX_FILE_BYTES, fmtBytesShort } from "@/lib/files-limits";

/**
 * Download one file, or a folder / multi-selection as a streamed .tar.gz, from the file browser.
 *
 * The bytes never pass through JavaScript: the browser downloads straight from our streaming route
 * through a hidden `<a download>`, so a multi-GB world file costs the page no memory and the browser's
 * own download manager provides the real progress bar, pause / resume and "open folder". What this hook
 * adds is everything the browser cannot: an archive is PRE-CHECKED first (a JSON verdict on size / file
 * count / missing tar), so a refusal is a clear in-page message rather than a failed download, and a
 * "Preparing" state shows while the server walks the selection.
 */
export type DownloadState = { busy: boolean; label: string | null };

function trigger(url: string) {
  const a = document.createElement("a");
  a.href = url;
  a.download = ""; // the server's Content-Disposition names the file
  a.rel = "noopener";
  a.style.display = "none";
  document.body.appendChild(a);
  a.click();
  setTimeout(() => a.remove(), 1000);
}

export function useFileDownload(
  api: FileApi,
  cbs: { onError: (m: string) => void; onNotice: (m: string) => void }
) {
  const [state, setState] = useState<DownloadState>({ busy: false, label: null });
  const apiRef = useRef(api);
  apiRef.current = api;
  const cbRef = useRef(cbs);
  cbRef.current = cbs;
  const running = useRef(false);

  const canDownload = !!api.downloadUrl;
  const canArchive = !!api.archiveUrl;

  /** Download `entries` that live in `dir`. One file -> direct; anything else -> .tar.gz. */
  const download = useCallback(async (dir: string, entries: FileEntry[]) => {
    const a = apiRef.current;
    const { onError, onNotice } = cbRef.current;
    if (running.current || entries.length === 0) return;
    const join = (n: string) => (dir === "/" ? `/${n}` : `${dir}/${n}`);

    if (entries.length === 1 && !entries[0].isDirectory) {
      const e = entries[0];
      const url = a.downloadUrl?.(join(e.name));
      if (!url) { onError("This server can't download files from here."); return; }
      if (e.size > MAX_FILE_BYTES) {
        onError(`${e.name} is ${fmtBytesShort(e.size)}, over the ${fmtBytesShort(MAX_FILE_BYTES)} browser-download limit. Download it with SFTP instead.`);
        return;
      }
      trigger(url);
      onNotice(`Downloading ${e.name} (${fmtBytesShort(e.size)}). Your browser shows the progress.`);
      return;
    }

    if (!a.archiveUrl) { onError("Folders can't be downloaded from this file manager yet."); return; }
    if (entries.length > MAX_ARCHIVE_ITEMS) {
      onError(`Select at most ${MAX_ARCHIVE_ITEMS} items at a time, or download the whole folder instead.`);
      return;
    }
    const names = entries.map((e) => e.name);
    running.current = true;
    setState({ busy: true, label: names.length === 1 ? `Preparing ${names[0]}…` : `Preparing ${names.length} items…` });
    try {
      const res = await fetch(a.archiveUrl(dir, names, { precheck: true }), { credentials: "same-origin", cache: "no-store" });
      const j = (await res.json().catch(() => null)) as
        | { ok: true; token: string; name: string; bytes: number | null; entries: number | null }
        | { ok: false; error: string }
        | null;
      if (!res.ok || !j || !j.ok) {
        onError(j && !j.ok ? j.error : res.status === 429 ? "Too many downloads — wait a moment and try again." : "Couldn't prepare that download.");
        return;
      }
      trigger(a.archiveUrl(dir, names, { token: j.token }));
      const size = j.bytes != null ? ` (about ${fmtBytesShort(j.bytes)} before compression)` : "";
      onNotice(`Downloading ${j.name}${size}. It is compressed as it streams, so the browser may not know the total size. Keep this tab open until it finishes.`);
    } catch {
      onError("Couldn't reach the server.");
    } finally {
      running.current = false;
      setState({ busy: false, label: null });
    }
  }, []);

  return { download, state, canDownload, canArchive };
}
