  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;
  const sp = req.nextUrl.searchParams;

  const user = await currentUser();
  if (!user) return jsonError("unauthorized", 401);

  const isArchive = sp.get("archive") === "1";
  const isPrecheck = sp.get("precheck") === "1";
  const rl = limited(user.id, isArchive ? (isPrecheck ? "precheck" : "archive") : "download", isArchive ? (isPrecheck ? 40 : 12) : 60);
  if (rl) return rl;

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return jsonError("not found", 404);

  const rq = { headers: req.headers, signal: req.signal, params: sp };
  const audit = (action: string, detail: string) => recordAudit(user.id, action, detail);
  return isArchive
    ? archiveResponse(rq, server, user.id, isPrecheck, audit)
    : fileResponse(rq, server, user.id, isPrecheck, audit);
}

