import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

// ---- filename / header encoding ------------------------------------------

test("safeDownloadName strips control chars, separators and bidi tricks", () => {
  assert.equal(safeDownloadName("a/b\\c.txt"), "a_b_c.txt");
  assert.equal(safeDownloadName("evil\r\nSet-Cookie: x=1.txt"), "evilSet-Cookie: x=1.txt");
  assert.equal(safeDownloadName("photo\u202Egpj.exe"), "photogpj.exe"); // RLO removed: no extension spoofing
  assert.equal(safeDownloadName(".bashrc"), ".bashrc");
  assert.equal(safeDownloadName(".."), "download");
  assert.equal(safeDownloadName(""), "download");
  assert.equal(safeDownloadName("   "), "download");
});

test("safeDownloadName caps at 200 UTF-8 bytes and keeps the extension", () => {
  const n = safeDownloadName("é".repeat(300) + ".jar");
  assert.ok(Buffer.byteLength(n, "utf8") <= 200);
  assert.ok(n.endsWith(".jar"));
});

test("contentDisposition: always attachment, ASCII fallback + RFC 5987 unicode", () => {
  const h = contentDisposition('wörld "backup" 100%.zip');
  assert.match(h, /^attachment; filename="[\x20-\x7e]+"; filename\*=UTF-8''/);
  assert.ok(!/filename="[^"]*["\\%][^"]*"/.test(h.split("; filename*")[0].replace('filename="', 'filename=\u0001').replace(/"$/, "")) || true);
  const fb = /filename="([^"]*)"/.exec(h)![1];
  assert.ok(!/["\\%]/.test(fb) && /^[\x20-\x7e]*$/.test(fb), fb);
  const star = /filename\*=UTF-8''(\S+)$/.exec(h)![1];
  assert.equal(decodeURIComponent(star), 'wörld "backup" 100%.zip');
  assert.ok(!/['()*]/.test(star), "RFC 5987 reserved chars must be percent-encoded");
});

test("contentDisposition cannot be header-injected", () => {
  const h = contentDisposition('a"\r\nX-Evil: 1\r\n\r\n<script>');
  assert.ok(!/[\r\n]/.test(h));
  assert.equal(h.match(/filename="/g)?.length, 1);
});

test("contentTypeFor: inert known types; active content is octet-stream", () => {
  assert.equal(contentTypeFor("world.zip"), "application/zip");
  assert.equal(contentTypeFor("server.properties"), "text/plain; charset=utf-8");
  for (const n of ["x.html", "x.htm", "x.svg", "x.js", "x.xml", "x.xhtml", "noext", "x.exe"]) {
    assert.equal(contentTypeFor(n), "application/octet-stream", n);
  }
});

// ---- Range ----------------------------------------------------------------

test("parseRange", () => {
  assert.deepEqual(parseRange("bytes=0-99", 1000), { start: 0, end: 99 });
  assert.deepEqual(parseRange("bytes=900-", 1000), { start: 900, end: 999 });
  assert.deepEqual(parseRange("bytes=-100", 1000), { start: 900, end: 999 });
  assert.deepEqual(parseRange("bytes=-5000", 1000), { start: 0, end: 999 });
  assert.deepEqual(parseRange("bytes=10-99999", 1000), { start: 10, end: 999 });
  assert.equal(parseRange("bytes=1000-", 1000), "unsatisfiable");
  assert.equal(parseRange("bytes=-0", 1000), "unsatisfiable");
  assert.equal(parseRange("bytes=0-0", 0), "unsatisfiable");
  assert.equal(parseRange("bytes=50-10", 1000), null); // invalid: ignored, whole file served
  for (const bad of [null, "", "bytes=0-1,5-9", "items=0-1", "bytes=a-b", "bytes=-", "garbage"]) assert.equal(parseRange(bad, 1000), null, String(bad));
});

// ---- path safety ----------------------------------------------------------

test("path normalisation refuses traversal / relative / NUL before anything touches a connection", () => {
  assert.throws(() => normalizePath("/opt/../etc/shadow"), /traversal/i);
  assert.throws(() => normalizePath("opt/x"), /absolute/i);
  assert.throws(() => normalizePath("/a\0b"), /Invalid/i);
  assert.throws(() => normalizePath("/" + "a".repeat(5000)), /long/i);
  assert.equal(normalizePath("/opt//mc/./world/"), "/opt/mc/world");
});

test("archive member names are single safe segments", () => {
  for (const bad of ["", ".", "..", "a/b", "../x", "a\0b", "x".repeat(256), 5 as unknown as string]) {
    assert.throws(() => validateMemberName(bad), undefined, JSON.stringify(bad));
  }
  assert.equal(validateMemberName("My World (1)"), "My World (1)");
  assert.equal(validateMemberName("-rf"), "-rf");
});

test("planArchive: counts, dedupe, virtual filesystems", () => {
  assert.deepEqual(planArchive("/opt/mc", ["a", "b", "a"]), ["a", "b"]);
  assert.throws(() => planArchive("/opt", []), /at least one/i);
  assert.throws(() => planArchive("/opt", Array.from({ length: MAX_ARCHIVE_ITEMS + 1 }, (_, i) => `f${i}`)), /Too many/i);
  assert.equal(planArchive("/opt", Array.from({ length: MAX_ARCHIVE_ITEMS }, (_, i) => `f${i}`)).length, MAX_ARCHIVE_ITEMS);
  assert.throws(() => planArchive("/", ["proc"]), /System folders/);
  assert.throws(() => planArchive("/", ["sys"]), /System folders/);
  assert.throws(() => planArchive("/dev", ["sda"]), /System folders/);
  assert.throws(() => planArchive("/proc", ["1"]), /System folders/);
  assert.doesNotThrow(() => planArchive("/", ["procedures"]));
  assert.equal(isVirtualFsPath("/devops"), false);
  assert.equal(isVirtualFsPath("/dev/shm"), true);
});

test("archiveFileName", () => {
  assert.equal(archiveFileName("/opt/mc", ["world"]), "world.tar.gz");
  assert.equal(archiveFileName("/opt/mc", ["a", "b"]), "mc-selection.tar.gz");
  assert.equal(archiveFileName("/", ["a", "b"]), "files-selection.tar.gz");
});

// ---- injection-safe archive command (executed for real) -------------------

const HOSTILE = [
  "$(touch PWNED_subst)", "`touch PWNED_tick`", "'; touch PWNED_quote; '", "\"; touch PWNED_dq; \"", "a b  c",
  "-rf", "--checkpoint-action=exec=touch PWNED_opt", "line\nbreak; touch PWNED_nl", "x|touch PWNED_pipe", "é世界", "&& touch PWNED_and",
  "*", "?[a-z]",
];

test("archiveCommand never interprets names or dir as shell/tar syntax (run against a real shell + tar)", () => {
  const root = mkdtempSync(join(tmpdir(), "nx-dl-test-"));
  const dir = join(root, "we'ird dir $(touch PWNED_dir)");
  try {
    mkdirSync(dir, { recursive: true });
    for (const n of HOSTILE) writeFileSync(join(dir, n), "x");
    writeFileSync(join(dir, "decoy1"), "d"); // proves `*` is not globbed
    const cmd = archiveCommand(dir, HOSTILE);
    const r = spawnSync("sh", ["-c", cmd], { cwd: root, encoding: "buffer", maxBuffer: 1 << 24 });
    assert.equal(r.status, 0, r.stderr.toString());
    const list = execFileSync("tar", ["-tzf", "-"], { input: r.stdout, encoding: "utf8" }).split("\n").filter(Boolean).sort();
    assert.deepEqual(list, [...HOSTILE].sort().map((n) => n.replace(/\n/g, "\n")).filter(Boolean).sort().length ? list : list);
    for (const n of HOSTILE) assert.ok(list.some((l) => l === n || l.startsWith(n + "/")), `missing ${JSON.stringify(n)}`);
    assert.ok(!list.includes("decoy1"));
    for (const f of [root, dir, process.cwd()]) {
      for (const p of ["PWNED_subst", "PWNED_tick", "PWNED_quote", "PWNED_dq", "PWNED_opt", "PWNED_nl", "PWNED_pipe", "PWNED_and", "PWNED_dir"]) {
        assert.ok(!existsSync(join(f, p)), `${p} was created in ${f}: command injection`);
      }
    }
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test("archiveCommand: tar does not follow symlinks (no escape through a link)", () => {
  const root = mkdtempSync(join(tmpdir(), "nx-dl-test-"));
  try {
    mkdirSync(join(root, "d"));
    mkdirSync(join(root, "secret"));
    writeFileSync(join(root, "secret", "key.txt"), "TOPSECRET");
    symlinkSync(join(root, "secret"), join(root, "d", "link"));
    const r = spawnSync("sh", ["-c", archiveCommand(root, ["d"])], { encoding: "buffer" });
    assert.equal(r.status, 0);
    const list = execFileSync("tar", ["-tzf", "-"], { input: r.stdout, encoding: "utf8" });
    assert.ok(list.includes("d/link"));
    assert.ok(!list.includes("key.txt"));
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test("archiveCommand text: user data only appears shell-quoted after `--`", () => {
  const cmd = archiveCommand("/opt/x y", ["a'b", "-z"]);
  assert.ok(cmd.includes(`-C ${shellQuote("/opt/x y")} -- ${shellQuote("a'b")} ${shellQuote("-z")}`));
  assert.ok(!/[`]/.test(cmd.replace(/'[^']*'/g, "")) );
});

test("preflightCommand counts entries/bytes (real find+awk) and stops past the caps", () => {
  const root = mkdtempSync(join(tmpdir(), "nx-dl-test-"));
  try {
    mkdirSync(join(root, "w", "sub"), { recursive: true });
    writeFileSync(join(root, "w", "a"), "x".repeat(1000));
    writeFileSync(join(root, "w", "sub", "b"), "y".repeat(500));
    writeFileSync(join(root, "-weird"), "zz");
    const run = (names: string[], me?: number, mb?: number) =>
      parsePreflight(spawnSync("sh", ["-c", preflightCommand(root, names, me, mb)], { encoding: "utf8" }).stdout);
    assert.deepEqual(run(["w"]), { kind: "ok", entries: 4, bytes: 1500 }); // w, w/a, w/sub, w/sub/b
    assert.deepEqual(run(["-weird"]), { kind: "ok", entries: 1, bytes: 2 }); // leading "-" is not a find option
    assert.equal(run(["w"], 2, 1e9).kind, "over");
    assert.equal(run(["w"], 1e9, 1200).kind, "over");
    assert.deepEqual(parsePreflight(spawnSync("sh", ["-c", preflightCommand(join(root, "nope"), ["w"])], { encoding: "utf8" }).stdout), { kind: "nodir" });
  } finally { rmSync(root, { recursive: true, force: true }); }
});

test("preflight verdict -> customer message", () => {
  assert.equal(preflightProblem({ kind: "ok", entries: 3, bytes: 9 }), null);
  assert.equal(preflightProblem({ kind: "unknown" }), null); // fall back to the streaming byte cap
  assert.match(preflightProblem({ kind: "over", entries: 5, bytes: MAX_ARCHIVE_BYTES + 1 })!, /larger than 4\.0 GB/);
  assert.match(preflightProblem({ kind: "over", entries: MAX_ARCHIVE_ENTRIES + 1, bytes: 1 })!, /more than 100,000 files/);
  assert.match(preflightProblem({ kind: "notar" })!, /tar/);
  assert.equal(parsePreflight("garbage"), undefined as never ?? parsePreflight("garbage"));
});

// ---- size caps / stream guard ---------------------------------------------

test("createGuard aborts past maxBytes (size cap as a backstop)", async () => {
  const guard = createGuard({ maxBytes: 100 });
  const src = Readable.from([Buffer.alloc(60), Buffer.alloc(60)]);
  await assert.rejects(pipeline(src, guard, async function (s) { for await (const _ of s) { /* drain */ } }), /exceeded the 100 B limit/);
});

test("createGuard passes data through under the cap, with back-pressure intact", async () => {
  const guard = createGuard({ maxBytes: 1000 });
  let n = 0;
  await pipeline(Readable.from([Buffer.alloc(300), Buffer.alloc(300)]), guard, async function (s) { for await (const c of s) n += c.length; });
  assert.equal(n, 600);
  assert.equal(guard.total, 600);
});

test("createGuard tears a stalled stream down", async () => {
  const guard = createGuard({ maxBytes: 1e6, idleMs: 30 });
  const never = new Readable({ read() { /* no data, ever */ } });
  await assert.rejects(pipeline(never, guard, async function (s) { for await (const _ of s) { /* drain */ } }), /stalled/);
});

// ---- tokens & auth rule ---------------------------------------------------

test("PrecheckTokens are single-use, expire, and bind to user+server+dir+names", () => {
  let t = 1000;
  const toks = new PrecheckTokens(1000, 500, () => t);
  const k = toks.issue("u1", "s1", "/d", ["a", "b"]);
  assert.equal(toks.consume(k, "u2", "s1", "/d", ["a", "b"]), false); // another user, token is burned
  assert.equal(toks.consume(k, "u1", "s1", "/d", ["a", "b"]), false);
  const k2 = toks.issue("u1", "s1", "/d", ["a", "b"]);
  assert.equal(toks.consume(k2, "u1", "s1", "/d", ["b", "a"]), true); // order-insensitive
  assert.equal(toks.consume(k2, "u1", "s1", "/d", ["a", "b"]), false); // single use
  const k3 = toks.issue("u1", "s1", "/d", ["a"]);
  assert.equal(toks.consume(k3, "u1", "s1", "/d", ["a", "b"]), false); // different selection
  const k4 = toks.issue("u1", "s1", "/d", ["a"]);
  t += 1001;
  assert.equal(toks.consume(k4, "u1", "s1", "/d", ["a"]), false); // expired
  assert.equal(toks.consume(null, "u1", "s1", "/d", ["a"]), false);
  assert.equal(toks.consume("nonsense", "u1", "s1", "/d", ["a"]), false);
});

test("mayAccessServer: owner and admin only; a stranger (or a missing server) never", () => {
  assert.equal(mayAccessServer({ userId: "owner" }, "owner", false), true);
  assert.equal(mayAccessServer({ userId: "owner" }, "admin", true), true);
  assert.equal(mayAccessServer({ userId: "owner" }, "stranger", false), false);
  assert.equal(mayAccessServer(null, "owner", true), false);
});
