test("file: streams with exact Content-Length, attachment disposition, nosniff, Range support", async () => {
  const r = await http.fileResponse(req("path=/data/big.bin&download=1"), server, "u1", false, audit);
  assert.equal(r.status, 200);
  assert.equal(r.headers.get("content-length"), "10000");
  assert.equal(r.headers.get("accept-ranges"), "bytes");
  assert.match(r.headers.get("content-disposition")!, /^attachment; filename="big\.bin"/);
  assert.equal(r.headers.get("x-content-type-options"), "nosniff");
