test("file: Range -> 206 with the exact slice; suffix; unsatisfiable -> 416; resumed range is not re-audited", async () => {
  const n = audits.length;
  const r = await http.fileResponse(req("path=/data/big.bin", { range: "bytes=5-14" }), server, "u1", false, audit);
  assert.equal(r.status, 206);
  assert.equal(r.headers.get("content-range"), "bytes 5-14/10000");
  assert.equal(r.headers.get("content-length"), "10");
  assert.equal(await text(r), "5678901234");
  const s = await http.fileResponse(req("path=/data/big.bin", { range: "bytes=-3" }), server, "u1", false, audit);
  assert.equal(await text(s), "789");
  const u = await http.fileResponse(req("path=/data/big.bin", { range: "bytes=10000-" }), server, "u1", false, audit);
  assert.equal(u.status, 416);
  assert.equal(u.headers.get("content-range"), "bytes */10000");
  assert.equal(audits.length, n, "ranges that do not start at 0 are resumptions");
  // If-Range that no longer matches -> the whole file, not a stale slice
  const f = await http.fileResponse(req("path=/data/big.bin", { range: "bytes=5-14", "if-range": "Wed, 01 Jan 2020 00:00:00 GMT" }), server, "u1", false, audit);
  assert.equal(f.status, 200);
