test("concurrency: slots are held while streaming and ALWAYS released (finish and client abort)", async () => {
  // 3 open, unread streams of the big file hold 3 slots; the 4th is refused; cancelling frees them.
  const held: Response[] = [];
  for (let i = 0; i < 3; i++) held.push(await http.fileResponse(req("path=/data/big.bin"), server, "slot-user", false, audit));
  const refused = await http.fileResponse(req("path=/data/big.bin"), server, "slot-user", false, audit);
  assert.equal(refused.status, 429);
  assert.equal(refused.headers.get("retry-after"), "5");
  // another user is unaffected
  const other = await http.fileResponse(req("path=/data/big.bin"), server, "someone-else", false, audit);
  assert.equal(other.status, 200); await other.arrayBuffer();
  for (const h of held) await h.body!.cancel(); // browser closed the tab
  await new Promise((r) => setTimeout(r, 50));
  const again = await http.fileResponse(req("path=/data/big.bin"), server, "slot-user", false, audit);
  assert.equal(again.status, 200);
  assert.equal((await again.arrayBuffer()).byteLength, 10000);
  await new Promise((r) => setTimeout(r, 20));
  const after = await http.fileResponse(req("path=/data/empty"), server, "slot-user", false, audit);
  assert.equal(after.status, 200); // slot freed after a normal finish too
});

