  await p.getByRole("button", { name: "Download folder (.tar.gz)" }).first().click();
  await p.waitForTimeout(500);
  await p.screenshot({ path: `${out}/folder-preparing-${tag}.png` });
  await dlp2; console.log(tag, "folder download", log.slice(-2));
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${out}/folder-started-${tag}.png` });
  // row menu open (on a folder and on a file)
  await p.getByRole("button", { name: "More actions" }).first().click();
  await p.waitForTimeout(200);
  await p.screenshot({ path: `${out}/row-menu-folder-${tag}.png` });
