  await p.getByLabel("Select plugins", { exact: true }).check();
  await p.getByLabel("Select server.properties").check();
  await p.waitForTimeout(200);
  await p.screenshot({ path: `${out}/multi-select-bar-${tag}.png`, fullPage: true });
  const dlp3 = p.waitForEvent("download");
  await p.getByTestId("download-selected").click();
  await p.waitForTimeout(500);
  await p.screenshot({ path: `${out}/multi-preparing-${tag}.png`, fullPage: true });
  await dlp3; console.log(tag, "multi download", log.slice(-2));
  // over-limit refusal (server 413 message) via backups folder
