  // single file over the 10 GB cap: client-side message, no request
  await p.getByLabel("Select world", { exact: true }).uncheck(); await p.getByLabel("Select plugins", { exact: true }).uncheck(); await p.getByLabel("Select server.properties").uncheck();
  const n = log.length;
